/bin/bash -lc "~/.venv/bin/python - <<'PY'
import importlib.util, onnx
from onnx import helper, TensorProto
spec=importlib.util.spec_from_file_location('b','tasks/task009/build.py'); b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
# monkeypatch checker to get raw model
old=onnx.checker.check_model;onnx.checker.check_model=lambda *a,**k:None
m=b.build_model();onnx.checker.check_model=old
for kind in ['sparse','tensor']:
 x=onnx.ModelProto();x.CopyFrom(m)
 for sp in x.graph.sparse_initializer:
  if kind=='sparse': vi=helper.make_sparse_tensor_value_info(sp.values.name, TensorProto.FLOAT, list(sp.dims))
  else: vi=helper.make_tensor_value_info(sp.values.name, TensorProto.FLOAT, list(sp.dims))
  x.graph.value_info.append(vi)
 try:
  old(x,full_check=True); print(kind,'PASS')
 except Exception as e: print(kind,'FAIL',e)
PY"

